request.query:
query getPhotoViewerItems($input: PhotoViewerInput, $isNmap: Boolean = false) {
  photoViewer(input: $input) {
    cursors {
      ...PhotoViewerCursorFragment
      __typename
    }
    photos {
      ...PhotoViewerImageFragment
      ...PhotoViewerImageNmapExtraFragment @include(if: $isNmap)
      __typename
    }
    __typename
  }
}

fragment PhotoViewerCursorFragment on PhotoViewerCursor {
  id
  startIndex
  hasNext
  lastCursor
  __typename
}

fragment PhotoViewerImageFragment on PhotoViewerImage {
  viewId
  originalUrl
  thumbnailUrl
  width
  height
  title
  date
  linkUrl
  description
  mediaFormat
  mediaSource
  visitorReview {
    visitCount
    votedKeywords {
      code
      iconUrl
      iconCode
      name
      __typename
    }
    isFollowing
    rating
    reviewGroupId
    reviewId
    __typename
  }
  option {
    channelName
    dateString
    playCount
    likeCount
    __typename
  }
  author {
    id
    nickname
    from
    imageUrl
    objectId
    url
    borderImageUrl
    officialYn
    __typename
  }
  externalLink {
    title
    url
    __typename
  }
  sourceTitle
  moment {
    channelId
    contentId
    momentId
    gdid
    blogRelation
    statAllowYn
    category
    docNo
    __typename
  }
  video {
    videoId
    videoUrl
    trailerUrl
    contentType
    __typename
  }
  music {
    artists
    title
    __typename
  }
  clip {
    serviceType
    createdAt
    contentType
    __typename
  }
  originType
  businessName
  __typename
}

fragment PhotoViewerImageNmapExtraFragment on PhotoViewerImage {
  visitorReview {
    visitCategories {
      code
      name
      keywords {
        code
        name
        __typename
      }
      __typename
    }
    __typename
  }
  author {
    followRequested
    __typename
  }
  __typename
}
